1670	/// Only certain instruction types are allowed in batches to prevent complex nested operations.
1671	fn verify_batch(
1672	    mut deps: DepsMut,
1673	    info: MessageInfo,
1674	    channel_id: ChannelId,
1675	    path: U256,
1676	    batch: &Batch,
1677	    response: &mut Response,
1678	) -> Result<(), ContractError> {
1679	    for instruction in &batch.instructions {
1680	        if !is_allowed_batch_instruction(instruction.opcode) {
1681	            return Err(ContractError::InvalidBatchInstruction);
1682	        }
1683	        verify_internal(
1684	            deps.branch(),
1685	            info.clone(),
1686	            channel_id,
1687	            path,
1688	            instruction,
1689	            response,
1690	        )?;
1691	    }
1692	    Ok(())
1693	}
